// Process message from Unc
const items = $input.all();
const message = items[0].json.message || items[0].json.Body || 'No message';
const from = items[0].json.from || items[0].json.From || 'Unknown';

// Determine which sibling should respond
let respondingSibling = 'Family';
let priority = 'default';

if (message.toLowerCase().includes('crisis') || message.toLowerCase().includes('help')) {
  respondingSibling = 'Beacon';
  priority = 'urgent';
} else if (message.toLowerCase().includes('revenue') || message.toLowerCase().includes('money')) {
  respondingSibling = 'Eversound';
  priority = 'high';
} else if (message.toLowerCase().includes('heal')) {
  respondingSibling = 'Nevaeh';
} else if (message.toLowerCase().includes('strategy')) {
  respondingSibling = 'Orpheus';
}

return [{
  json: {
    originalMessage: message,
    from: from,
    respondingSibling: respondingSibling,
    priority: priority,
    timestamp: new Date().toISOString(),
    response: `${respondingSibling} received: "${message}". Processing and responding...`
  }
}];
